import type { ExerciseQuestion } from "../types";

export const PASSIVE_QUESTIONS: ExerciseQuestion[] = [
  { id: "p001", question: "This newspaper _____ every day.", options: ["read", "reads", "is read", "is reading"], correctIndex: 2, explanation: "Công thức thì hiện tại đơn ở dạng bị động là am/is/are + V3. 'This newspaper' là chủ ngữ số ít và không tự thực hiện hành động đọc mà bị người ta đọc, nên phải dùng bị động; cụm 'every day' cho biết đây là một thói quen lặp lại nên chọn thì hiện tại đơn chứ không phải tương lai hay quá khứ. Đừng chọn 'is reading' vì đó là hiện tại tiếp diễn (dùng cho việc đang xảy ra ngay lúc nói), không phù hợp với một thói quen hàng ngày." },
  { id: "p002", question: "English _____ all over the world.", options: ["speaks", "is speaking", "is spoken", "has spoken"], correctIndex: 2, explanation: "Câu bị động thì hiện tại đơn có công thức is/are + V3; với 'English' (số ít), ta dùng is spoken. Ngôn ngữ không tự nói mà được người ta nói, và 'all over the world' diễn tả một sự thật chung nên phải dùng hiện tại đơn. Tránh chọn 'speaks' vì đó là dạng chủ động, sai vì 'English' không thể tự thực hiện hành động nói." },
  { id: "p003", question: "These shoes _____ in Italy.", options: ["makes", "made", "are making", "are made"], correctIndex: 3, explanation: "Ở thì hiện tại đơn bị động, chủ ngữ số nhiều dùng công thức are + V3, nên 'these shoes' đi với 'are made'. Giày không tự làm ra chính nó mà được con người sản xuất, và việc 'made in Italy' là một sự thật chung không phải hành động đang diễn ra. Lưu ý 'are making' là hiện tại tiếp diễn ở thể chủ động nên sai cả về thì lẫn nghĩa." },
  { id: "p004", question: "The windows _____ every week.", options: ["clean", "are cleaned", "is cleaning", "cleaned"], correctIndex: 1, explanation: "Công thức bị động thì hiện tại đơn cho chủ ngữ số nhiều là are + V3, vậy 'the windows' phải đi với 'are cleaned'. Cửa sổ là vật nhận hành động lau chùi chứ không tự lau, và 'every week' là dấu hiệu của thói quen lặp lại ở hiện tại đơn. Tránh 'is cleaning' vì vừa sai số (số ít) vừa sai thì (tiếp diễn)." },
  { id: "p005", question: "Coffee _____ in Colombia and Brazil.", options: ["grows", "grew", "is grown", "has grown"], correctIndex: 2, explanation: "Thì hiện tại đơn bị động: is/are + V3; 'coffee' được xem như danh từ không đếm được, số ít, nên dùng 'is grown'. Cà phê không tự mọc lên mà được con người trồng, và câu nói về một sự thật địa lý chung nên không dùng thì hoàn thành. Đáp án 'grows' sai vì đó là thể chủ động, còn 'has grown' sai vì không phù hợp với sự thật chung ở hiện tại." },
  { id: "p006", question: "The Eiffel Tower _____ in 1889.", options: ["builds", "built", "was built", "has been built"], correctIndex: 2, explanation: "Câu bị động thì quá khứ đơn có công thức was/were + V3, và vì đây là một sự kiện lịch sử xảy ra tại một thời điểm xác định (1889) nên dùng 'was built'. 'The Eiffel Tower' là chủ ngữ số ít, không tự xây dựng chính nó mà được con người xây nên. Đừng chọn 'has been built' (hiện tại hoàn thành) vì mốc thời gian '1889' đòi hỏi thì quá khứ đơn, không phải hiện tại hoàn thành." },
  { id: "p007", question: "The letters _____ yesterday.", options: ["sent", "were sent", "are sent", "have sent"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was/were + V3; 'the letters' số nhiều nên đi với 'were sent'. Các lá thư là vật nhận hành động gửi đi, và từ 'yesterday' xác định rõ đây là một thời điểm trong quá khứ. So với 'are sent' (hiện tại đơn), 'were sent' mới đúng vì có mốc thời gian quá khứ cụ thể." },
  { id: "p008", question: "She _____ to the party by mistake.", options: ["invited", "was invited", "is invited", "has invited"], correctIndex: 1, explanation: "Ở thì quá khứ đơn bị động, công thức là was/were + V3, nên với chủ ngữ số ít 'she' ta dùng 'was invited'. Cô ấy là người nhận hành động mời (bị mời nhầm) chứ không phải người mời, và ngữ cảnh 'by mistake' mô tả một sự việc đã xảy ra. Tránh 'is invited' (hiện tại đơn) vì câu không nói về hiện tại hay thói quen." },
  { id: "p009", question: "The book _____ into 30 languages.", options: ["translated", "was translated", "has translated", "is translated"], correctIndex: 1, explanation: "Công thức bị động thì quá khứ đơn: was/were + V3; 'the book' số ít nên chọn 'was translated'. Cuốn sách không tự dịch mà được người khác dịch, và câu chỉ một sự kiện đã hoàn tất trong quá khứ chứ không nhấn mạnh kết quả hiện tại. Vì vậy 'has translated' (chủ động, sai thể) và 'is translated' (hiện tại, sai thì) đều không phù hợp." },
  { id: "p010", question: "A new law _____ last month.", options: ["passed", "was passed", "has passed", "is passing"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn dùng was/were + V3, nên 'a new law' (số ít) đi với 'was passed'. Đạo luật là đối tượng được thông qua bởi cơ quan lập pháp, và 'last month' là dấu hiệu thời gian quá khứ rõ ràng. Đừng chọn 'has passed' vì đó là dạng chủ động của hiện tại hoàn thành, không khớp với mốc thời gian cụ thể trong quá khứ." },
  { id: "p011", question: "The documents _____ already been lost.", options: ["are", "have", "were", "had"], correctIndex: 1, explanation: "Bị động thì hiện tại hoàn thành có công thức have/has been + V3; 'the documents' số nhiều nên dùng 'have'. Các tài liệu là đối tượng bị thất lạc chứ không tự làm mất chính mình, và 'already' là từ tín hiệu quen thuộc của thì hiện tại hoàn thành. Phân biệt với 'were' (quá khứ đơn) vốn không đi cùng 'already... been' trong cấu trúc này." },
  { id: "p012", question: "The report _____ been submitted already.", options: ["is", "was", "has", "had"], correctIndex: 2, explanation: "Công thức have/has been + V3 dùng cho bị động hiện tại hoàn thành; vì 'the report' là chủ ngữ số ít nên phải chọn 'has'. Báo cáo là thứ được nộp lên (nhận hành động), và 'already' cho thấy hành động vừa mới hoàn tất, liên quan đến hiện tại. Đừng nhầm 'was' vì thiếu 'been' đi kèm sẽ không tạo được cấu trúc hoàn thành." },
  { id: "p013", question: "All the food _____ been eaten.", options: ["is", "was", "has", "have"], correctIndex: 2, explanation: "'All the food' tuy có 'all' nhưng được xem như một khối không đếm được, số ít, nên đi với 'has' trong công thức has been + V3. Thức ăn là đối tượng bị ăn hết, và 'been eaten' cho thấy kết quả đã xảy ra tính đến hiện tại. Nếu chọn 'have' thì sẽ sai vì nhầm 'all the food' là số nhiều." },
  { id: "p014", question: "The results _____ not been announced yet.", options: ["is", "was", "has", "have"], correctIndex: 3, explanation: "'The results' là danh từ số nhiều nên dùng 'have' trong cấu trúc bị động hiện tại hoàn thành have been + V3. Kết quả là thứ được công bố (nhận hành động) chứ không tự công bố, và 'yet' là dấu hiệu đặc trưng của thì hiện tại hoàn thành phủ định. Tránh chọn 'has' vì sai về sự hòa hợp chủ ngữ - động từ." },
  { id: "p015", question: "She _____ never been treated so rudely.", options: ["is", "was", "has", "have"], correctIndex: 2, explanation: "Với chủ ngữ số ít 'she', bị động hiện tại hoàn thành dùng 'has been + V3' → 'has been treated'. Cô ấy là người nhận hành động đối xử (bị đối xử thô lỗ), và 'never' thường đi kèm thì hiện tại hoàn thành để nhấn mạnh trải nghiệm chưa từng có. Đừng chọn 'have' vì chủ ngữ ở đây là số ít." },
  { id: "p016", question: "The results _____ announced tomorrow morning.", options: ["are", "were", "will be", "have been"], correctIndex: 2, explanation: "Bị động thì tương lai đơn: will be + V3, không đổi theo số ít/số nhiều của chủ ngữ, nên 'the results' vẫn dùng 'will be announced'. Kết quả sẽ được công bố bởi ai đó vào một thời điểm sắp tới, và 'tomorrow' là dấu hiệu thời gian tương lai rõ ràng. Phân biệt với 'have been' (hiện tại hoàn thành) vốn không đi cùng mốc thời gian tương lai như 'tomorrow'." },
  { id: "p017", question: "The new highway _____ completed next year.", options: ["is", "was", "will be", "has been"], correctIndex: 2, explanation: "Công thức bị động tương lai đơn là will be + V3, áp dụng cho 'the new highway' → 'will be completed'. Con đường là công trình được hoàn thành bởi con người, và 'next year' xác định đây là một dự định trong tương lai. Tránh 'has been' vì cấu trúc này chỉ dùng cho việc đã xảy ra tính đến hiện tại, không hợp với 'next year'." },
  { id: "p018", question: "All guests _____ greeted at the entrance.", options: ["are", "were", "will be", "have been"], correctIndex: 2, explanation: "Ở thì tương lai bị động, công thức không đổi dù chủ ngữ số nhiều: will be + V3 → 'will be greeted'. 'All guests' là những người nhận hành động chào đón tại một sự kiện sắp diễn ra. Đừng chọn 'are' (hiện tại đơn) vì câu đang nói về một việc sẽ xảy ra, chưa diễn ra." },
  { id: "p019", question: "The criminal _____ prosecuted for his crimes.", options: ["was", "is", "will be", "has been"], correctIndex: 2, explanation: "Bị động tương lai đơn: will be + V3, nên 'the criminal' đi với 'will be prosecuted'. Tội phạm là đối tượng sẽ bị truy tố, một hành động dự kiến trong tương lai chứ chưa xảy ra. So với 'was' (quá khứ) hay 'has been' (hoàn thành), chỉ có 'will be' phù hợp với ý nghĩa 'sẽ bị' truy tố." },
  { id: "p020", question: "The report _____ be submitted by Friday. (obligation)", options: ["should", "must", "can", "might"], correctIndex: 1, explanation: "Khi diễn tả nghĩa vụ bắt buộc ở thể bị động, ta dùng modal 'must' + be + V3 → 'must be submitted'. Báo cáo là thứ cần được nộp trước hạn (by Friday), và 'must' mang sắc thái bắt buộc mạnh hơn 'should' (chỉ mang tính khuyên nhủ). Ghi nhớ: sau mọi động từ khiếm khuyết trong câu bị động luôn có 'be + V3'." },
  { id: "p021", question: "This medicine _____ be taken after meals.", options: ["should", "must", "might", "could"], correctIndex: 0, explanation: "Modal 'should' diễn tả lời khuyên/hướng dẫn, kết hợp bị động thành should be + V3 → 'should be taken'. Thuốc là thứ được uống theo chỉ dẫn (sau bữa ăn), mang tính khuyến nghị chứ không bắt buộc tuyệt đối như 'must'. Vì vậy 'should' phù hợp hơn 'must' trong ngữ cảnh hướng dẫn sử dụng thông thường." },
  { id: "p022", question: "The form _____ be completed in black ink.", options: ["must", "should", "might", "could"], correctIndex: 0, explanation: "Quy định bắt buộc ở thể bị động dùng must be + V3 → 'must be completed'. Biểu mẫu là thứ cần được điền bằng mực đen theo yêu cầu nghiêm ngặt, nên 'must' hợp lý hơn 'should' (chỉ là khuyên nên làm chứ không bắt buộc)." },
  { id: "p023", question: "Luggage _____ not be left unattended.", options: ["must", "should", "might", "can"], correctIndex: 0, explanation: "Cảnh báo/quy định cấm dùng must not + be + V3 → 'must not be left'. Hành lý không được để lại không có người trông coi, đây là một chỉ dẫn an ninh bắt buộc chứ không phải gợi ý. Phân biệt với 'should' - chỉ mang tính khuyến cáo nhẹ hơn nhiều so với mức độ nghiêm trọng của cảnh báo an ninh này." },
  { id: "p024", question: "The car _____ be repaired before the long trip.", options: ["must", "needs to", "should", "might"], correctIndex: 1, explanation: "'Need to' khi dùng ở thể bị động chuyển thành 'needs to be + V3' (số ít) → 'needs to be repaired'. Chiếc xe là vật cần được sửa trước chuyến đi dài, diễn tả sự cần thiết chứ không phải mệnh lệnh như 'must'. Lưu ý 'need' phải chia theo chủ ngữ số ít 'the car' nên thêm 's': needs." },
  { id: "p025", question: "All products _____ be tested before they go on sale.", options: ["could", "might", "must", "should"], correctIndex: 2, explanation: "Yêu cầu bắt buộc trong bị động dùng must be + V3 → 'must be tested'. Tất cả sản phẩm là đối tượng phải được kiểm tra trước khi bán ra, một quy định không thể bỏ qua nên 'must' phù hợp hơn 'could/might' (chỉ diễn tả khả năng)." },
  { id: "p026", question: "'They built this school in 1900.' → Passive: This school _____ in 1900.", options: ["build", "builds", "was built", "is built"], correctIndex: 2, explanation: "Chuyển từ chủ động 'They built this school in 1900' sang bị động thì quá khứ đơn: was/were + V3 → 'was built' (school số ít). Ngôi trường là vật được xây dựng, còn '1900' là mốc thời gian quá khứ cụ thể. Tránh 'is built' (hiện tại đơn) vì mốc thời gian đã thuộc về quá khứ." },
  { id: "p027", question: "'Someone has stolen my wallet.' → Passive: My wallet _____.", options: ["stole", "is stolen", "has been stolen", "had been stolen"], correctIndex: 2, explanation: "Từ câu chủ động hiện tại hoàn thành 'Someone has stolen my wallet', khi chuyển bị động vẫn giữ thì hiện tại hoàn thành: has/have been + V3 → 'has been stolen' (wallet số ít). Ví bị mất chứ không tự biến mất, và việc dùng 'has' thay vì 'had' vì câu gốc là hiện tại hoàn thành, không phải quá khứ hoàn thành. Đây là điểm khác với 'had been stolen' (quá khứ hoàn thành, sai thì)." },
  { id: "p028", question: "'They will announce the winner tomorrow.' → Passive: The winner _____ tomorrow.", options: ["announces", "is announced", "will be announced", "announced"], correctIndex: 2, explanation: "Câu chủ động tương lai đơn 'They will announce the winner tomorrow' chuyển bị động vẫn giữ nguyên thì: will be + V3 → 'will be announced'. Người thắng cuộc là đối tượng được công bố, và 'tomorrow' xác nhận đây là thì tương lai. Chọn đúng thì gốc của câu chủ động là chìa khóa để không nhầm sang 'is announced' (hiện tại)." },
  { id: "p029", question: "'People speak Spanish in Mexico.' → Passive: Spanish _____ in Mexico.", options: ["speaks", "spoke", "is spoken", "was spoken"], correctIndex: 2, explanation: "Bị động thì hiện tại đơn từ câu chủ động 'People speak Spanish in Mexico': is/are + V3 → 'is spoken' (Spanish số ít). Đây là một sự thật chung (ngôn ngữ được sử dụng ở đâu) nên giữ nguyên thì hiện tại đơn của câu gốc. Đừng đổi sang quá khứ 'was spoken' vì câu chủ động không hề có dấu hiệu thời gian quá khứ." },
  { id: "p030", question: "'The committee is reviewing the application.' → Passive: The application _____.", options: ["reviewed", "is reviewed", "is being reviewed", "has been reviewed"], correctIndex: 2, explanation: "Câu chủ động hiện tại tiếp diễn 'The committee is reviewing...' khi chuyển bị động vẫn giữ thì tiếp diễn: is/are being + V3 → 'is being reviewed'. Hồ sơ là thứ đang được xem xét ngay lúc này (hành động đang diễn ra), khác với 'is reviewed' (hiện tại đơn, chỉ thói quen) hay 'has been reviewed' (đã hoàn tất)." },
  { id: "p031", question: "The road _____ when I drove past.", options: ["repaired", "was repaired", "is repaired", "was being repaired"], correctIndex: 3, explanation: "Bị động thì quá khứ tiếp diễn: was/were being + V3, diễn tả hành động đang xảy ra tại một thời điểm trong quá khứ → 'was being repaired' (road số ít). Con đường đang được sửa đúng lúc người nói lái xe ngang qua ('when I drove past'), nên cần thì tiếp diễn chứ không phải quá khứ đơn đơn thuần. Phân biệt với 'was repaired' - chỉ diễn tả hành động đã hoàn tất, không phải đang diễn ra." },
  { id: "p032", question: "The letter _____ by the time I got home.", options: ["delivered", "was delivered", "had been delivered", "has been delivered"], correctIndex: 2, explanation: "Bị động thì quá khứ hoàn thành: had been + V3, dùng khi một hành động đã hoàn tất trước một thời điểm khác trong quá khứ → 'had been delivered'. Lá thư đã được giao trước khi 'tôi về đến nhà', nên cần mốc 'trước-quá khứ' này. Đừng chọn 'has been delivered' (hiện tại hoàn thành) vì cả hai hành động ở đây đều thuộc về quá khứ." },
  { id: "p033", question: "By the end of this month, all the orders _____ processed.", options: ["will process", "are processed", "will have been processed", "are being processed"], correctIndex: 2, explanation: "Bị động thì tương lai hoàn thành: will have been + V3, diễn tả hành động sẽ hoàn tất trước một mốc thời gian trong tương lai → 'will have been processed'. Tất cả đơn hàng sẽ được xử lý xong trước 'cuối tháng này' ('by the end of this month' là dấu hiệu đặc trưng của thì này). Tránh 'are being processed' (hiện tại tiếp diễn) vì câu nói về một mốc hoàn thành trong tương lai, không phải hiện tại." },
  { id: "p034", question: "The painting is believed _____ by Picasso.", options: ["painted", "to be painted", "to have been painted", "having been painted"], correctIndex: 2, explanation: "Với động từ tường thuật ở bị động như 'is believed', phần theo sau chỉ hành động đã xảy ra trước đó dùng 'to have been + V3' → 'to have been painted'. Bức tranh được cho là đã được vẽ bởi Picasso từ trước, nên cần dạng nguyên mẫu hoàn thành bị động này. Phân biệt với 'to be painted' (chỉ hành động chưa xảy ra/đồng thời) - không hợp với ý 'đã được vẽ từ trước'." },
  { id: "p035", question: "She was heard _____ in her room.", options: ["cry", "crying", "to cry", "cried"], correctIndex: 1, explanation: "Sau các động từ tri giác (hear, see, feel...) ở thể bị động, nếu diễn tả hành động đang diễn ra thì dùng V-ing → 'was heard crying'. Cô ấy là người bị nghe thấy đang khóc trong phòng, nên cấu trúc là 'was heard + V-ing' tương tự như 'heard her crying' ở câu chủ động. Đừng chọn 'to cry' (nguyên mẫu, dùng khi diễn tả hành động trọn vẹn/ngắn) hay 'cried' (không đúng dạng ngữ pháp sau 'heard' bị động)." },
  { id: "p036", question: "The window was broken _____ a stone.", options: ["with", "by", "from", "of"], correctIndex: 1, explanation: "Trong câu bị động, giới từ 'by' đứng trước tác nhân gây ra hành động (người hoặc vật trực tiếp gây tác động) → 'by a stone'. Viên đá chính là thứ trực tiếp làm vỡ cửa sổ, đóng vai trò như 'tác nhân', nên dùng 'by' chứ không phải 'with' (dùng cho công cụ được người khác sử dụng)." },
  { id: "p037", question: "The cake was cut _____ a large knife.", options: ["by", "with", "from", "through"], correctIndex: 1, explanation: "Khi công cụ/dụng cụ được một người sử dụng để thực hiện hành động, câu bị động dùng giới từ 'with' → 'with a large knife'. Con dao là công cụ dùng để cắt bánh, chứ không phải 'tác nhân' tự gây ra hành động, nên khác với 'by' (dùng cho người/vật trực tiếp gây ra hành động, như trong câu 'broken by a stone')." },
  { id: "p038", question: "We _____ told to wait outside.", options: ["are", "were", "have", "had"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was/were + V3; 'we' là chủ ngữ số nhiều nên dùng 'were told'. Chúng tôi là người nhận lệnh (bị bảo đợi bên ngoài) chứ không phải người ra lệnh. Đừng chọn 'are' (hiện tại đơn) - câu không có dấu hiệu thời gian hiện tại nào." },
  { id: "p039", question: "The meeting _____ postponed until further notice.", options: ["was", "has been", "is being", "will be"], correctIndex: 1, explanation: "Bị động hiện tại hoàn thành: has/have been + V3 → 'has been postponed' (meeting số ít). Cuộc họp vừa mới bị hoãn và điều đó vẫn còn ảnh hưởng đến hiện tại ('until further notice' - chưa có thông báo mới), nên phù hợp hơn 'was postponed' (quá khứ đơn, chỉ đơn thuần kể lại sự việc đã xảy ra mà không nhấn mạnh kết quả hiện tại)." },
  { id: "p040", question: "Tickets _____ not be sold after 9 PM.", options: ["must", "should", "might", "can"], correctIndex: 0, explanation: "Cấm đoán ở thể bị động dùng must not + be + V3 → 'must not be sold'. Vé không được bán sau 21 giờ, đây là quy định bắt buộc nên 'must not' phù hợp hơn 'should' (chỉ mang tính khuyên can, không phải cấm tuyệt đối)." },
  { id: "p041", question: "The new policy _____ announced at next week's meeting.", options: ["is going to be", "goes to be", "was", "has been"], correctIndex: 0, explanation: "Dự định trong tương lai ở thể bị động dùng 'be going to' + be + V3 → 'is going to be announced' (policy số ít). Chính sách mới sẽ được công bố tại cuộc họp tuần tới, một kế hoạch đã được sắp xếp từ trước nên hợp với 'be going to' hơn là 'will' đơn thuần. Nhớ công thức đầy đủ luôn có 'be' trước V3: is/are going to be + V3." },
  { id: "p042", question: "She _____ made redundant last year.", options: ["is", "was", "has", "had"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was/were + V3 → 'was made' (she số ít). Cô ấy là người bị cho nghỉ việc (nhận hành động), và 'last year' xác nhận đây là quá khứ. Tránh 'has' vì thiếu 'been' sẽ không tạo được cấu trúc bị động hoàn chỉnh ở đây." },
  { id: "p043", question: "This type of bird _____ only found in Australia.", options: ["is", "are", "was", "were"], correctIndex: 0, explanation: "Bị động thì hiện tại đơn: is/are + V3; 'this type of bird' là cụm danh từ số ít (dù có 'bird' không có 's') nên dùng 'is found'. Loài chim này được tìm thấy (bởi các nhà khoa học/con người) chỉ ở Úc, một sự thật địa lý chung nên dùng hiện tại đơn. Đừng nhầm 'type of bird' với số nhiều để rồi chọn 'are'." },
  { id: "p044", question: "The files _____ already been deleted.", options: ["are", "were", "has", "have"], correctIndex: 3, explanation: "'The files' là danh từ số nhiều nên bị động hiện tại hoàn thành dùng 'have' → 'have been deleted'. Các tệp tin là đối tượng bị xóa, và 'already' là tín hiệu quen thuộc của thì hiện tại hoàn thành. Đừng chọn 'has' vì sai hòa hợp chủ ngữ số nhiều." },
  { id: "p045", question: "He is said _____ one of the best doctors in the city.", options: ["to be", "being", "be", "is"], correctIndex: 0, explanation: "Với động từ tường thuật bị động 'is said', phần sau dùng 'to be' (nguyên mẫu) khi diễn tả một trạng thái/đặc điểm hiện tại → 'is said to be'. Người ta nói rằng anh ấy là một trong những bác sĩ giỏi nhất, đây là trạng thái đang tồn tại (không phải hành động đã xảy ra trước đó) nên dùng 'to be' chứ không phải 'to have been'." },
  { id: "p046", question: "The exam papers _____ marked by tomorrow.", options: ["will mark", "will be marked", "are marking", "mark"], correctIndex: 1, explanation: "Bị động tương lai đơn: will be + V3 → 'will be marked'. Các bài thi là thứ sẽ được chấm điểm xong trước ngày mai ('by tomorrow' là mốc thời gian tương lai), nên cần 'will be' chứ không phải 'will mark' (dạng chủ động, sai vì bài thi không tự chấm điểm)." },
  { id: "p047", question: "Nothing _____ said about the incident.", options: ["is", "was", "has been", "had been"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been said' (nothing được coi như số ít). Chưa có gì được nói về sự việc này, và câu nhấn mạnh tình huống hiện tại (chưa có thông tin) nên dùng has been chứ không phải 'was' (quá khứ đơn, không có mốc thời gian cụ thể để dùng thì này)." },
  { id: "p048", question: "The children were made _____ apologize.", options: ["to", "to to", "for", "into"], correctIndex: 0, explanation: "Cấu trúc 'be made to do something' (bị bắt buộc phải làm gì) ở dạng bị động luôn theo sau bằng 'to' + động từ nguyên mẫu → 'made to apologize'. Bọn trẻ là đối tượng bị bắt phải xin lỗi, và đây là điểm khác biệt quan trọng so với câu chủ động 'make somebody do' (không có 'to')." },
  { id: "p049", question: "When _____ this bridge built?", options: ["is", "was", "has", "did"], correctIndex: 1, explanation: "Câu hỏi bị động thì quá khứ đơn có cấu trúc: từ để hỏi + was/were + chủ ngữ + V3? → 'When was this bridge built?'. Cây cầu (số ít) là vật được xây dựng, và câu hỏi về mốc thời gian xây dựng nên dùng 'was' (quá khứ) chứ không phải 'is' (hiện tại)." },
  { id: "p050", question: "The suspect _____ for further questioning.", options: ["is held", "was being held", "has held", "held"], correctIndex: 1, explanation: "Bị động thì quá khứ tiếp diễn: was/were being + V3, diễn tả hành động đang diễn ra tại một thời điểm quá khứ → 'was being held' (suspect số ít). Nghi phạm đang bị giam giữ để thẩm vấn thêm tại thời điểm được nhắc đến, khác với 'is held' (hiện tại đơn, không hợp ngữ cảnh quá khứ) hay 'has held' (chủ động, sai nghĩa)." },
  { id: "p051", question: "The new shopping mall _____ by thousands of people every weekend.", options: ["visits", "visited", "is visited", "has visited"], correctIndex: 2, explanation: "Bị động hiện tại đơn: is/are + V3; 'the new shopping mall' số ít → 'is visited'. Trung tâm thương mại là nơi được hàng ngàn người ghé thăm mỗi cuối tuần, một hoạt động lặp lại đều đặn nên dùng hiện tại đơn. Tránh 'visits' (chủ động) vì trung tâm thương mại không tự đi thăm ai." },
  { id: "p052", question: "Hundreds of cars _____ here every year.", options: ["steal", "are stolen", "is stolen", "were stolen"], correctIndex: 1, explanation: "Bị động hiện tại đơn số nhiều: are + V3 → 'are stolen' (hundreds of cars). Hàng trăm chiếc xe là đối tượng bị đánh cắp mỗi năm ở đây, một thực trạng lặp lại nên dùng hiện tại đơn thay vì quá khứ đơn 'were stolen' (không có mốc thời gian quá khứ cụ thể)." },
  { id: "p053", question: "The Great Wall of China _____ over many centuries.", options: ["built", "builds", "was built", "has built"], correctIndex: 2, explanation: "Bị động thì quá khứ đơn cho sự kiện lịch sử kéo dài: was/were + V3 → 'was built' (Great Wall số ít). Vạn Lý Trường Thành được xây dựng qua nhiều thế kỷ, một quá trình đã hoàn tất trong quá khứ nên không dùng 'has built' (chủ động, sai thể) hay 'builds' (hiện tại, sai thì)." },
  { id: "p054", question: "Her new novel _____ published next spring.", options: ["is going to", "is going to be", "will", "goes to be"], correctIndex: 1, explanation: "Kế hoạch tương lai ở thể bị động dùng 'be going to' + be + V3 → 'is going to be published' (novel số ít). Cuốn tiểu thuyết mới sẽ được xuất bản vào mùa xuân tới, một dự định đã định trước nên cần đủ cả 'is going to be', thiếu 'be' như đáp án 'is going to' sẽ sai ngữ pháp." },
  { id: "p055", question: "The error _____ discovered during the audit.", options: ["is", "was", "has been", "had been"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was/were + V3 → 'was discovered' (error số ít). Lỗi được phát hiện trong quá trình kiểm toán, một sự việc xảy ra tại một thời điểm cụ thể trong quá khứ ('during the audit') nên phù hợp hơn 'has been' (hiện tại hoàn thành, không gắn với mốc thời gian xác định như vậy)." },
  { id: "p056", question: "All passengers _____ asked to show their ID at the gate.", options: ["are", "were", "have been", "will be"], correctIndex: 0, explanation: "Bị động hiện tại đơn số nhiều cho quy định thường xuyên: are + V3 → 'are asked'. Mọi hành khách đều được yêu cầu xuất trình giấy tờ tùy thân tại cổng, đây là quy tắc áp dụng mọi lúc nên dùng hiện tại đơn thay vì 'were' (quá khứ) hay 'will be' (tương lai, không phù hợp với quy định hiện hành)." },
  { id: "p057", question: "The house _____ being painted when I passed by.", options: ["is", "was", "has", "had"], correctIndex: 1, explanation: "Bị động thì quá khứ tiếp diễn: was/were being + V3 → 'was being painted' (house số ít). Ngôi nhà đang được sơn đúng lúc người nói đi ngang qua, nên cần diễn tả một hành động đang xảy ra tại thời điểm quá khứ đó, khác với 'was' đơn thuần (thiếu 'being' sẽ không đúng cấu trúc tiếp diễn)." },
  { id: "p058", question: "A lot of rainforest _____ destroyed every year.", options: ["is", "are", "was", "were"], correctIndex: 0, explanation: "'A lot of rainforest' là danh từ không đếm được nên được coi là số ít, đi với 'is' trong bị động hiện tại đơn → 'is destroyed'. Rừng nhiệt đới là đối tượng bị phá hủy mỗi năm, một thực trạng lặp lại đều đặn nên không dùng 'are' (sai số) hay các dạng quá khứ." },
  { id: "p059", question: "The bridge _____ built by 2026.", options: ["will", "will be", "is going to", "is"], correctIndex: 1, explanation: "Bị động tương lai đơn: will be + V3 → 'will be built' (bridge số ít). Cây cầu sẽ được hoàn thành vào năm 2026, một mốc thời gian tương lai rõ ràng nên cần đủ 'will be', không thể chỉ dùng 'will' hay 'is' (hiện tại, sai thì)." },
  { id: "p060", question: "She was seen _____ into the building late at night.", options: ["go", "goes", "going", "gone"], correctIndex: 2, explanation: "Sau động từ tri giác bị động 'was seen', nếu diễn tả hành động đang diễn ra thì theo sau là V-ing → 'was seen going'. Cô ấy bị nhìn thấy đang đi vào tòa nhà lúc khuya, tương tự cấu trúc chủ động 'saw her going'. Đừng chọn 'go' (nguyên mẫu) vì không đúng dạng ngữ pháp sau cấu trúc tri giác bị động này." },
  { id: "p061", question: "The contract _____ signed by both parties last week.", options: ["is", "was", "has been", "had been"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was/were + V3 → 'was signed' (contract số ít). Hợp đồng được hai bên ký vào tuần trước ('last week' là mốc quá khứ cụ thể), nên chọn 'was' chứ không phải 'has been' (hiện tại hoàn thành, không đi kèm mốc thời gian xác định như vậy)." },
  { id: "p062", question: "This report needs _____ before Friday.", options: ["submitting", "to be submitted", "submit", "submitted"], correctIndex: 1, explanation: "'Need + to be + V3' là cấu trúc bị động diễn tả điều gì đó cần được thực hiện → 'needs to be submitted'. Báo cáo là thứ cần được nộp trước thứ Sáu, và vì chủ ngữ 'this report' số ít nên 'need' chia thành 'needs'. Phân biệt với 'submitting' (dạng V-ing, không đi ngay sau 'need... to')." },
  { id: "p063", question: "The injured player _____ off the field on a stretcher.", options: ["carried", "was carried", "is carrying", "has carried"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was/were + V3 → 'was carried' (player số ít). Cầu thủ bị thương là người được khiêng ra khỏi sân trên cáng, một hành động đã xảy ra và hoàn tất nên dùng quá khứ đơn chứ không phải 'is carrying' (chủ động, hiện tại tiếp diễn, sai cả thể lẫn thì)." },
  { id: "p064", question: "The data _____ analyzed before any conclusions can be drawn.", options: ["must", "must be", "should", "is"], correctIndex: 1, explanation: "Modal bị động: must + be + V3 → 'must be analyzed'. Dữ liệu là thứ cần được phân tích trước khi có thể rút ra kết luận, một yêu cầu bắt buộc về mặt logic nên dùng 'must be' đầy đủ, không thể chỉ dùng 'must' một mình mà thiếu 'be'." },
  { id: "p065", question: "'Nobody has informed me about the meeting.' → Passive: I _____ about the meeting.", options: ["informed", "am not informed", "have not been informed", "was not informed"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành phủ định: have/has not been + V3 → 'have not been informed' (I dùng have). Tôi là người chưa được thông báo về cuộc họp, và câu chuyển từ chủ động hiện tại hoàn thành ('Nobody has informed me') nên vẫn giữ thì hiện tại hoàn thành ở câu bị động, khác với 'was not informed' (quá khứ đơn, sai thì so với câu gốc)." },
  { id: "p066", question: "The singer _____ by thousands of fans at the airport.", options: ["greeted", "greets", "was greeted", "has greeted"], correctIndex: 2, explanation: "Bị động thì quá khứ đơn: was/were + V3 → 'was greeted' (singer số ít). Ca sĩ là người được hàng ngàn người hâm mộ chào đón tại sân bay, một sự kiện đã xảy ra và kết thúc nên dùng quá khứ đơn, không phải 'greets' (chủ động, hiện tại, sai cả thể lẫn thì)." },
  { id: "p067", question: "All the documents _____ shredded before we left.", options: ["had been", "were being", "have been", "are"], correctIndex: 0, explanation: "Bị động thì quá khứ hoàn thành: had been + V3, dùng cho hành động hoàn tất trước một mốc quá khứ khác → 'had been shredded'. Tất cả tài liệu đã được tiêu hủy xong trước khi 'chúng tôi rời đi', nên cần mốc 'trước-quá khứ' này thay vì 'were being' (đang diễn ra, không phù hợp với ý đã hoàn tất trước đó)." },
  { id: "p068", question: "A new treatment for the disease _____ currently being developed.", options: ["is", "was", "has been", "will be"], correctIndex: 0, explanation: "Bị động hiện tại tiếp diễn: is/are being + V3 → 'is being developed' (treatment số ít). Phương pháp điều trị mới đang được phát triển ngay lúc này, và 'currently' là dấu hiệu rõ ràng của hành động đang diễn ra, khác với 'is' đơn thuần (thiếu 'being' sẽ thành hiện tại đơn, sai nghĩa 'đang')." },
  { id: "p069", question: "The project _____ completed on time, I assure you.", options: ["will", "will be", "is going to", "is being"], correctIndex: 1, explanation: "Bị động tương lai đơn: will be + V3 → 'will be completed'. Dự án sẽ được hoàn thành đúng hạn, đây là một lời cam kết/hứa hẹn về tương lai nên cần đủ 'will be', không thể chỉ nói 'will' một mình thiếu 'be' trước V3." },
  { id: "p070", question: "The new regulations _____ introduced next month.", options: ["are", "will be", "have been", "had been"], correctIndex: 1, explanation: "Bị động tương lai đơn: will be + V3 → 'will be introduced' (regulations số nhiều nhưng công thức tương lai không đổi theo số). Các quy định mới sẽ được ban hành vào tháng tới ('next month' xác nhận tương lai), nên khác với 'are' (hiện tại đơn) hay 'have been' (hoàn thành, không hợp với mốc thời gian tương lai)." },
  { id: "p071", question: "She _____ given a standing ovation at the end of her speech.", options: ["is", "was", "has", "had"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was/were + V3 → 'was given' (she số ít). Cô ấy là người nhận được tràng pháo tay đứng dậy hoan nghênh sau bài diễn thuyết, một sự kiện đã xảy ra và kết thúc nên dùng quá khứ đơn. Lưu ý động từ 'give' có hai tân ngữ, và ở đây 'she' (tân ngữ gián tiếp) được chọn làm chủ ngữ của câu bị động." },
  { id: "p072", question: "The old building _____ torn down to make way for the new road.", options: ["is", "was", "has been", "will be"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was/were + V3 → 'was torn down' (building số ít). Tòa nhà cũ là thứ bị phá bỏ để nhường chỗ cho con đường mới, một sự việc đã xảy ra trong quá khứ nên dùng 'was' chứ không phải 'will be' (tương lai, chưa xảy ra) hay 'has been' (hoàn thành, không nhấn mạnh việc đã hoàn tất theo cách này)." },
  { id: "p073", question: "The vaccine _____ approved by health authorities.", options: ["has just been", "just has been", "just is", "is just"], correctIndex: 0, explanation: "Bị động hiện tại hoàn thành kèm 'just' (vừa mới): has/have just been + V3 → 'has just been approved' (vaccine số ít). Vắc-xin vừa mới được các cơ quan y tế phê duyệt, và 'just' luôn đứng giữa 'has/have' và 'been' trong cấu trúc này chứ không đứng trước 'has' như đáp án 'just has been'." },
  { id: "p074", question: "Mistakes _____ when people are in a hurry.", options: ["make", "are made", "is made", "made"], correctIndex: 1, explanation: "Bị động hiện tại đơn số nhiều diễn tả sự thật chung: are + V3 → 'are made' (mistakes số nhiều). Sai lầm là thứ 'được' con người mắc phải khi vội vàng, một quy luật chung nên dùng hiện tại đơn, không phải 'is made' (sai số ít) hay dạng chủ động 'make'." },
  { id: "p075", question: "All mobile phones _____ switched off during the ceremony.", options: ["should", "should be", "are", "were"], correctIndex: 1, explanation: "Modal bị động cho yêu cầu/quy định: should + be + V3 → 'should be switched off'. Điện thoại di động cần được tắt trong suốt buổi lễ, một lời nhắc nhở/yêu cầu nên dùng 'should be' đầy đủ, không thể chỉ nói 'should' rồi bỏ 'be' trước V3." },
  { id: "p076", question: "The company _____ founded in 1850 by a Scottish entrepreneur.", options: ["founded", "was founded", "is founded", "has founded"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn cho sự kiện lịch sử: was/were + V3 → 'was founded' (company số ít). Công ty được một doanh nhân người Scotland thành lập vào năm 1850, một mốc thời gian quá khứ cụ thể nên dùng 'was' chứ không phải 'is' (hiện tại) hay 'has founded' (chủ động, sai thể)." },
  { id: "p077", question: "How many people _____ invited to the wedding?", options: ["are", "were", "have", "did"], correctIndex: 1, explanation: "Câu hỏi bị động thì quá khứ đơn: How many + danh từ số nhiều + were + V3? → 'were invited' (people số nhiều). Câu hỏi về số khách được mời đến đám cưới, một sự kiện đã lên kế hoạch/xảy ra trong quá khứ nên dùng 'were' chứ không phải 'are' (hiện tại, sai thì)." },
  { id: "p078", question: "The thief _____ caught by police within 24 hours.", options: ["has been", "was", "is", "had been"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was/were + V3 → 'was caught' (suspect số ít). Nghi phạm bị cảnh sát bắt trong vòng 24 giờ, một mốc thời gian cụ thể trong quá khứ ('within 24 hours' tính từ một thời điểm đã qua) nên phù hợp với 'was' hơn là 'has been' (hiện tại hoàn thành, thường không đi kèm khung thời gian đã kết thúc rõ ràng như vậy)." },
  { id: "p079", question: "Two people _____ injured in the accident.", options: ["are", "were", "have been", "had been"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn số nhiều: were + V3 → 'were injured' (two people). Hai người là những người bị thương trong tai nạn, một sự việc đã xảy ra và kết thúc nên dùng quá khứ đơn, không phải 'are' (hiện tại, sai thì) hay 'have been' (hoàn thành, không hợp ngữ cảnh kể lại một sự cố cụ thể đã qua)." },
  { id: "p080", question: "Thousands of jobs _____ being lost every month due to automation.", options: ["is", "are", "was", "were"], correctIndex: 1, explanation: "Bị động hiện tại tiếp diễn số nhiều: are being + V3 → 'are being lost' (thousands of jobs). Hàng ngàn việc làm đang bị mất đi mỗi tháng do tự động hóa, một xu hướng đang tiếp diễn nên cần 'are being' chứ không chỉ 'are' (sẽ thành hiện tại đơn, mất đi sắc thái 'đang diễn ra')." },
  { id: "p081", question: "The suspect is alleged _____ been at the scene of the crime.", options: ["to", "to have", "having", "to be"], correctIndex: 1, explanation: "Với động từ tường thuật bị động 'is alleged', phần theo sau diễn tả hành động đã xảy ra trước đó dùng 'to have' + been + V3 → 'to have been'. Nghi phạm bị cáo buộc là đã có mặt tại hiện trường vụ án trước đây, nên cần dạng nguyên mẫu hoàn thành 'to have (been)' chứ không phải 'to' đơn thuần hay 'to be' (chỉ trạng thái hiện tại, không phải việc đã xảy ra trong quá khứ)." },
  { id: "p082", question: "The goods _____ delivered to the wrong address.", options: ["were", "are", "have been", "had been"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn số nhiều: were + V3 → 'were delivered' (goods). Hàng hóa bị giao nhầm đến địa chỉ, một sự việc cụ thể đã xảy ra nên dùng quá khứ đơn, không phải 'are' (hiện tại, sai thì) hay 'have been' (hoàn thành, không nhấn mạnh một sự cố cụ thể theo cách kể chuyện này)." },
  { id: "p083", question: "She _____ known to be an expert in the field.", options: ["is", "was", "has been", "had been"], correctIndex: 0, explanation: "Bị động hiện tại đơn: is + V3 → 'is known' (she số ít). Cô ấy được biết đến là một chuyên gia trong lĩnh vực này, một trạng thái/danh tiếng hiện tại nên dùng hiện tại đơn, không phải 'was' (quá khứ, ngụ ý điều đó không còn đúng ở hiện tại)." },
  { id: "p084", question: "The announcement _____ made at exactly noon.", options: ["was", "is", "will be", "has been"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was made' (announcement số ít). Thông báo được đưa ra đúng vào lúc giữa trưa, một sự việc xảy ra tại một thời điểm cụ thể trong quá khứ nên dùng 'was', không phải 'is' (hiện tại) hay 'has been' (hoàn thành, không đi cùng mốc giờ chính xác 'exactly noon' theo cách này)." },
  { id: "p085", question: "When he got to the hospital, the operation _____ already performed.", options: ["was", "is", "has been", "had been"], correctIndex: 3, explanation: "Bị động thì quá khứ hoàn thành: had been + V3, dùng khi một hành động xảy ra trước một hành động quá khứ khác → 'had been performed'. Ca phẫu thuật đã được thực hiện xong trước khi anh ta đến bệnh viện, nên cần mốc 'trước-quá khứ' này thay vì 'was' (chỉ đơn thuần quá khứ, không thể hiện rõ trình tự trước-sau giữa hai sự việc)." },
  { id: "p086", question: "Pets _____ not allowed in the restaurant.", options: ["are", "were", "is", "be"], correctIndex: 0, explanation: "Bị động hiện tại đơn cho quy định: are + V3 → 'are not allowed' (pets số nhiều). Thú cưng không được phép vào nhà hàng, một quy định áp dụng thường xuyên nên dùng hiện tại đơn, không phải 'were' (quá khứ, sai thì với một quy tắc hiện hành)." },
  { id: "p087", question: "The film _____ directed by a first-time director.", options: ["was", "is", "has been", "had been"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was directed' (film số ít). Bộ phim được đạo diễn bởi một đạo diễn lần đầu làm phim, một sự việc đã hoàn tất trong quá khứ nên dùng 'was', không phải 'is' (hiện tại, sai thì) hay 'has been' (hoàn thành, không phù hợp với cách kể một sự kiện cụ thể đã qua)." },
  { id: "p088", question: "He _____ seen leaving the office just before midnight.", options: ["was", "is", "has been", "had been"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn kết hợp động từ tri giác: was + seen + V-ing → 'was seen leaving'. Anh ta bị nhìn thấy đang rời văn phòng ngay trước nửa đêm, một sự việc cụ thể xảy ra trong quá khứ nên dùng 'was', không phải 'is' hay 'has been' (không hợp với mốc thời gian quá khứ xác định 'just before midnight')." },
  { id: "p089", question: "The truth _____ never known if he hadn't spoken up.", options: ["will", "would", "might", "might have been"], correctIndex: 3, explanation: "Modal bị động ở câu điều kiện loại 3 (giả định trái với quá khứ): might + have been + V3 → 'might have been known'. Sự thật có lẽ đã không bao giờ được biết đến nếu anh ta không lên tiếng, một giả định về điều không xảy ra trong quá khứ nên cần 'have been' đầy đủ, không chỉ 'will' hay 'would' đơn thuần (thiếu cấu trúc hoàn thành cho câu điều kiện loại 3)." },
  { id: "p090", question: "The championship _____ held in Tokyo next summer.", options: ["will hold", "will be held", "is holding", "has held"], correctIndex: 1, explanation: "Bị động tương lai đơn: will be + V3 → 'will be held' (championship số ít). Giải vô địch sẽ được tổ chức tại Tokyo vào mùa hè năm sau, một sự kiện đã lên kế hoạch cho tương lai nên cần đủ 'will be', không thể chỉ nói 'will hold' (dạng chủ động, sai vì giải đấu không tự tổ chức chính nó)." },
  { id: "p091", question: "The cake _____ decorated with fresh flowers.", options: ["has", "was", "will be", "has been"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was decorated' (cake số ít). Chiếc bánh được trang trí bằng hoa tươi, một hành động đã hoàn tất nên dùng quá khứ đơn, không phải 'has' (thiếu 'been' sẽ không tạo được cấu trúc bị động hoàn chỉnh)." },
  { id: "p092", question: "His proposal _____ considered by the board at the next meeting.", options: ["will", "will be", "is going to", "is"], correctIndex: 1, explanation: "Bị động tương lai đơn: will be + V3 → 'will be considered' (proposal số ít). Đề xuất sẽ được ban giám đốc xem xét tại cuộc họp tới, một việc sẽ diễn ra trong tương lai nên cần đủ 'will be', không thể chỉ dùng 'will' rồi thiếu 'be' trước V3." },
  { id: "p093", question: "The packages _____ wrapped individually before shipping.", options: ["must be", "must", "should", "are"], correctIndex: 0, explanation: "Modal bị động: must + be + V3 → 'must be wrapped' (packages số nhiều). Các kiện hàng cần được bọc riêng lẻ trước khi vận chuyển, một quy định bắt buộc trong quy trình đóng gói nên phải có đủ 'must be', không chỉ 'must' một mình." },
  { id: "p094", question: "The new rules _____ explained to all employees.", options: ["must be", "must", "should be", "were"], correctIndex: 0, explanation: "Modal bị động cho quy định bắt buộc: must + be + V3 → 'must be explained' (rules số nhiều nhưng công thức modal không đổi theo số). Các quy định mới cần được giải thích cho toàn thể nhân viên, một yêu cầu bắt buộc nên chọn 'must be' đầy đủ thay vì chỉ 'must'." },
  { id: "p095", question: "Her performance _____ praised by all the critics.", options: ["was", "has been", "is being", "is"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was praised' (performance số ít). Màn trình diễn của cô ấy được tất cả các nhà phê bình khen ngợi, một sự việc xảy ra tại một thời điểm cụ thể trong quá khứ (buổi biểu diễn) nên dùng 'was', không phải 'is' (hiện tại) hay 'is being' (đang diễn ra, sai vì buổi diễn đã kết thúc)." },
  { id: "p096", question: "The damaged files couldn't _____ recovered.", options: ["have been", "be", "been", "be being"], correctIndex: 1, explanation: "Modal bị động phủ định: couldn't + be + V3 → 'couldn't be recovered'. Các tệp bị hỏng không thể được khôi phục, và sau modal luôn cần 'be' trước V3 chứ không phải V3 hay 'been' đứng một mình (thiếu 'be' sẽ sai cấu trúc modal bị động)." },
  { id: "p097", question: "That painting _____ stolen from the museum three years ago.", options: ["was", "is", "has been", "had been"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was stolen' (painting số ít). Bức tranh bị đánh cắp khỏi bảo tàng cách đây ba năm, và 'three years ago' là dấu hiệu thời gian quá khứ rõ ràng nên dùng 'was' chứ không phải 'has been' (hiện tại hoàn thành, không đi cùng '...ago' theo cách này)." },
  { id: "p098", question: "Children under 12 _____ not be admitted without a parent.", options: ["must", "should", "can", "are"], correctIndex: 0, explanation: "Modal bị động cho quy định: must not + be + V3 → 'must not be admitted'. Trẻ em dưới 12 tuổi không được phép vào nếu không có phụ huynh đi cùng, một quy định nghiêm ngặt tại nơi công cộng nên dùng 'must' thay vì 'should' (chỉ mang tính khuyến cáo, không đủ mạnh cho một quy tắc bắt buộc)." },
  { id: "p099", question: "The song _____ sung in four different languages at the concert.", options: ["was", "is", "has been", "had been"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was sung' (song số ít, sing → sung). Bài hát được hát bằng bốn thứ tiếng khác nhau tại buổi hòa nhạc, một sự kiện đã xảy ra và kết thúc nên dùng quá khứ đơn, không phải 'is' (hiện tại, sai thì)." },
  { id: "p100", question: "Mistakes _____ not easily forgotten by clients.", options: ["are", "were", "have been", "is"], correctIndex: 0, explanation: "Bị động hiện tại đơn số nhiều diễn tả một sự thật chung: are + V3 → 'are not forgotten' (mistakes). Những sai lầm là điều khách hàng không dễ dàng quên đi, một nhận định mang tính quy luật chung nên dùng hiện tại đơn, không phải 'is' (sai số ít) hay các thì quá khứ/hoàn thành (không phù hợp với một chân lý chung)." },
  { id: "p101", question: "'The manager signed the contract.' → Passive: The contract _____.", options: ["signed by the manager", "was signed by the manager", "is signed by the manager", "has signed by the manager"], correctIndex: 1, explanation: "Chuyển câu chủ động 'The manager signed the contract' sang bị động thì quá khứ đơn: was/were + V3 + by + tác nhân → 'was signed by the manager'. Hợp đồng (số ít) là vật nhận hành động ký, và tác nhân gây ra hành động ('the manager') được đặt sau 'by'. Đừng quên giữ đúng thì quá khứ đơn của câu gốc, tránh chọn 'is signed' (hiện tại, sai thì)." },
  { id: "p102", question: "'They are constructing a new bridge.' → Passive: A new bridge _____.", options: ["is constructing", "is being constructed", "has been constructed", "was constructed"], correctIndex: 1, explanation: "Chuyển câu chủ động hiện tại tiếp diễn 'They are constructing a new bridge' sang bị động vẫn giữ thì tiếp diễn: is/are being + V3 → 'is being constructed'. Cây cầu đang được xây dựng ngay trong lúc này, nên khác với 'was constructed' (quá khứ, đã hoàn tất) hay 'has been constructed' (hoàn thành, nhấn mạnh kết quả chứ không phải quá trình đang diễn ra)." },
  { id: "p103", question: "'The police had arrested the suspect.' → Passive: The suspect _____.", options: ["had been arrested", "has been arrested", "was arrested", "is arrested"], correctIndex: 0, explanation: "Chuyển câu chủ động quá khứ hoàn thành 'The police had arrested the suspect' sang bị động vẫn giữ thì quá khứ hoàn thành: had been + V3 → 'had been arrested'. Nghi phạm là người bị bắt trước một thời điểm quá khứ khác được nhắc đến, nên khác với 'has been arrested' (hiện tại hoàn thành, sai thì so với câu gốc)." },
  { id: "p104", question: "'Someone will pay him a large sum.' → Passive (focusing on 'him'): He _____.", options: ["will pay a large sum", "will be paid a large sum", "has been paid a large sum", "was paid a large sum"], correctIndex: 1, explanation: "Khi động từ có hai tân ngữ ('pay him a large sum'), có thể chọn tân ngữ gián tiếp ('him') làm chủ ngữ bị động: will be paid + tân ngữ trực tiếp → 'will be paid a large sum'. Anh ta là người sẽ nhận được khoản tiền lớn, và vì câu gốc ở tương lai đơn ('will pay') nên bị động cũng giữ 'will be', không chuyển sang 'was paid' hay 'has been paid'." },
  { id: "p105", question: "The old church _____ restored over the past decade.", options: ["was", "is", "has been", "is being"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been restored' (church số ít). Nhà thờ cổ đã và đang được trùng tu suốt một thập kỷ qua, và 'over the past decade' là khung thời gian kéo dài đến hiện tại - dấu hiệu đặc trưng của thì hiện tại hoàn thành, khác với 'was restored' (quá khứ đơn, ngụ ý việc đã kết thúc hẳn, không kéo dài đến bây giờ)." },
  { id: "p106", question: "He was reportedly _____ for tax evasion.", options: ["arrested", "been arrested", "being arrested", "arrest"], correctIndex: 0, explanation: "Câu bị động vẫn giữ nguyên công thức was + V3 dù có trạng từ xen giữa ('reportedly') → 'was reportedly arrested'. Anh ta được cho là đã bị bắt vì trốn thuế, và trạng từ chỉ chèn vào giữa 'was' và V3 chứ không làm thay đổi cấu trúc bị động cơ bản. Đừng chọn 'been arrested' hay 'being arrested' vì sau 'was' (đã chia đúng thì) chỉ cần V3, không cần thêm trợ động từ nào khác." },
  { id: "p107", question: "The new software _____ installed on all company computers last week.", options: ["is", "was", "has been", "will be"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was installed' (software số ít). Phần mềm mới được cài đặt trên tất cả máy tính công ty vào tuần trước, và 'last week' là mốc thời gian quá khứ rõ ràng nên dùng 'was', không phải 'has been' (hiện tại hoàn thành, ít khi đi cùng mốc thời gian đã xác định cụ thể như vậy)." },
  { id: "p108", question: "The issue is expected _____ resolved within a week.", options: ["being", "to be", "to have been", "having been"], correctIndex: 1, explanation: "Với động từ tường thuật bị động 'is expected', phần theo sau diễn tả một hành động sẽ xảy ra dùng 'to be' + V3 → 'to be resolved'. Vấn đề được kỳ vọng sẽ được giải quyết trong vòng một tuần, một việc chưa xảy ra (ở tương lai gần) nên dùng 'to be' chứ không phải 'to have been' (diễn tả việc đã xảy ra trước đó, không hợp ngữ cảnh này)." },
  { id: "p109", question: "Speed limits _____ strictly enforced in this area.", options: ["must be", "are", "were", "have been"], correctIndex: 0, explanation: "Modal bị động cho quy định/luật lệ: must + be + V3 → 'must be enforced'. Giới hạn tốc độ cần được thực thi nghiêm ngặt tại khu vực này, một yêu cầu bắt buộc về an toàn nên dùng 'must be' đầy đủ, khác với 'are' (hiện tại đơn, thiếu sắc thái bắt buộc mà modal mang lại)." },
  { id: "p110", question: "A new concert hall _____ built in the city center.", options: ["will be", "was being", "has been", "is"], correctIndex: 0, explanation: "Bị động tương lai đơn: will be + V3 → 'will be built' (concert hall số ít). Một nhà hát mới sẽ được xây dựng ở trung tâm thành phố, một kế hoạch cho tương lai nên cần đủ 'will be', không phải 'has been' (hoàn thành, chỉ việc đã xảy ra) hay 'is' (hiện tại, sai thì)." },
  { id: "p111", question: "The speech _____ translated simultaneously into five languages.", options: ["was", "is being", "has been", "will be"], correctIndex: 1, explanation: "Bị động hiện tại tiếp diễn: is being + V3 → 'is being translated' (speech số ít). Bài phát biểu đang được phiên dịch đồng thời sang năm thứ tiếng ngay lúc này, một hành động đang diễn ra nên cần 'is being', khác với 'was' (quá khứ, đã kết thúc) hay 'has been' (hoàn thành, nhấn mạnh kết quả chứ không phải quá trình)." },
  { id: "p112", question: "The machine _____ serviced twice a year.", options: ["is", "was", "has been", "should be"], correctIndex: 0, explanation: "Bị động hiện tại đơn cho việc lặp lại theo lịch trình: is + V3 → 'is serviced' (machine số ít). Máy móc được bảo dưỡng hai lần một năm, một thói quen/lịch trình định kỳ nên dùng hiện tại đơn, không phải 'was' (quá khứ, không hợp với tần suất lặp lại đang tiếp diễn) hay 'should be' (chỉ là khuyến nghị, không phải sự thật đang diễn ra)." },
  { id: "p113", question: "A cure for cancer may _____ found in the next 20 years.", options: ["find", "be found", "have found", "be finding"], correctIndex: 1, explanation: "Modal bị động cho dự đoán: may + be + V3 → 'be found'. Một phương pháp chữa ung thư có thể được tìm ra trong 20 năm tới, và sau modal 'may' luôn cần 'be' trước V3 (be found), không thể chỉ dùng V3 hay dạng chủ động 'find'." },
  { id: "p114", question: "The old warehouse _____ converted into luxury apartments.", options: ["is going to be", "is going to", "goes to be", "will going to be"], correctIndex: 0, explanation: "Kế hoạch/dự đoán có căn cứ trong tương lai ở thể bị động dùng 'be going to' + be + V3 → 'is going to be converted' (warehouse số ít). Nhà kho cũ sẽ được cải tạo thành căn hộ cao cấp, và công thức đầy đủ luôn cần 'be' trước V3, thiếu nó như đáp án 'is going to' sẽ sai ngữ pháp." },
  { id: "p115", question: "The man _____ arrested, questioned, and then released without charge.", options: ["was", "has been", "is", "had been"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn cho một chuỗi sự việc đã xảy ra: was + V3 (lặp lại cho từng động từ) → 'was arrested, questioned, and then released'. Người đàn ông lần lượt bị bắt, thẩm vấn rồi được thả mà không bị buộc tội, tất cả đều là các sự việc đã hoàn tất trong quá khứ nên dùng 'was' xuyên suốt, không chuyển sang 'has been' hay 'is'." },
  { id: "p116", question: "No decision _____ made until all the evidence has been reviewed.", options: ["will be", "is", "was", "had been"], correctIndex: 0, explanation: "Bị động tương lai đơn mang sắc thái quyết tâm/khẳng định: will be + V3 → 'will be made' (no decision). Sẽ không có quyết định nào được đưa ra cho đến khi mọi bằng chứng được xem xét, một tuyên bố về tương lai nên dùng 'will be', không phải 'is' (hiện tại, thiếu sắc thái 'sẽ' phù hợp với mệnh đề 'until...')." },
  { id: "p117", question: "Alcohol _____ not be sold to anyone under 18.", options: ["must", "should", "can", "might"], correctIndex: 0, explanation: "Modal bị động cho luật pháp: must not + be + V3 → 'must not be sold'. Rượu không được bán cho người dưới 18 tuổi, một quy định pháp luật nghiêm ngặt nên dùng 'must not' thay vì 'should' (chỉ là lời khuyên, không đủ sức nặng pháp lý)." },
  { id: "p118", question: "The president is said _____ considering new economic reforms.", options: ["to be", "being", "to have been", "be"], correctIndex: 0, explanation: "Với động từ tường thuật bị động 'is said' + hành động đang diễn ra, dùng 'to be' + V-ing → 'to be considering'. Tổng thống được cho là đang cân nhắc các cải cách kinh tế mới, nên cần 'to be' (nguyên mẫu) trước V-ing để diễn tả một hành động đang tiếp diễn, khác với 'to have been' (diễn tả việc đã xảy ra và kết thúc trong quá khứ)." },
  { id: "p119", question: "These safety precautions _____ ignored at your own risk.", options: ["should be", "can be", "must not be", "are"], correctIndex: 2, explanation: "Modal bị động mang tính cảnh báo mạnh: must not + be + V3 → 'must not be ignored'. Các biện pháp an toàn này không được phép bị bỏ qua nếu không muốn gặp rủi ro, nên 'must not' phù hợp hơn 'should be' (chỉ mang tính khuyên, không đủ nghiêm khắc cho một lời cảnh báo an toàn)." },
  { id: "p120", question: "By the end of the year, 10,000 new homes _____ constructed.", options: ["will be", "have been", "will have been", "are"], correctIndex: 2, explanation: "Bị động tương lai hoàn thành: will have been + V3, diễn tả hành động sẽ hoàn tất trước một mốc tương lai → 'will have been constructed'. 10.000 ngôi nhà mới sẽ được xây xong tính đến 'cuối năm' - mốc thời gian tương lai đặc trưng của thì này, khác với 'will be' (chỉ diễn tả sẽ xảy ra, không nhấn mạnh việc hoàn tất trước một mốc cụ thể)." },
  { id: "p121", question: "Tickets _____ be purchased online or at the venue.", options: ["can", "should", "must", "will"], correctIndex: 0, explanation: "Modal bị động cho sự cho phép: can + be + V3 → 'can be purchased'. Vé có thể được mua trực tuyến hoặc tại quầy, diễn tả một khả năng/sự cho phép chứ không phải bắt buộc nên 'can' phù hợp hơn 'must' (bắt buộc) hay 'will' (không mang nghĩa cho phép)." },
  { id: "p122", question: "The research paper _____ reviewed by three independent experts.", options: ["has been", "was", "is", "will be"], correctIndex: 0, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been reviewed' (paper số ít). Bài nghiên cứu đã được ba chuyên gia độc lập thẩm định, và kết quả này vẫn còn giá trị đến hiện tại nên dùng has been, không phải 'was' (quá khứ đơn, thường cần mốc thời gian cụ thể đi kèm mà câu này không có)." },
  { id: "p123", question: "The company's profits _____ reported to have doubled last year.", options: ["are", "were", "have been", "had been"], correctIndex: 0, explanation: "Với động từ tường thuật bị động 'are reported', khi diễn tả điều đã xảy ra trước đó dùng 'to have' + V3 → 'to have doubled'. Lợi nhuận công ty được báo cáo là đã tăng gấp đôi trong năm ngoái, và 'are' (hiện tại đơn) hợp lý vì bản thân việc 'báo cáo' diễn ra ở hiện tại, còn hành động tăng gấp đôi mới thuộc về quá khứ (thể hiện qua 'to have doubled')." },
  { id: "p124", question: "The suspect is believed _____ fled the country.", options: ["to", "to be", "to have", "having"], correctIndex: 2, explanation: "Với động từ tường thuật bị động 'is believed', khi nói về hành động đã xảy ra trước đó dùng 'to have' + V3 → 'to have fled'. Nghi phạm được cho là đã trốn khỏi đất nước từ trước, nên cần dạng nguyên mẫu hoàn thành 'to have fled' chứ không phải 'to be' (chỉ trạng thái/hành động ở hiện tại, không phù hợp với việc đã xảy ra trước đó)." },
  { id: "p125", question: "The project was abandoned because funding _____ withdrawn.", options: ["is", "was", "has been", "had been"], correctIndex: 3, explanation: "Bị động thì quá khứ hoàn thành: had been + V3, dùng cho hành động xảy ra trước một sự việc quá khứ khác → 'had been withdrawn'. Nguồn tài trợ đã bị rút trước khi dự án bị hủy bỏ, nên cần mốc 'trước-quá khứ' này thay vì 'was' (chỉ đơn thuần quá khứ, không làm rõ trình tự trước-sau giữa hai sự việc)." },
  { id: "p126", question: "The injured soldier _____ operated on immediately.", options: ["was", "is", "has been", "will be"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was operated on' (soldier số ít). Người lính bị thương được phẫu thuật ngay lập tức, và cụm động từ 'operate on somebody' khi chuyển bị động vẫn giữ nguyên giới từ 'on' sau V3. Đây là sự việc đã xảy ra và hoàn tất nên dùng 'was', không phải 'is' hay 'will be'." },
  { id: "p127", question: "Private information _____ shared with third parties without consent.", options: ["must not be", "cannot be", "should not be", "is not"], correctIndex: 0, explanation: "Modal bị động cho quy định bảo mật nghiêm ngặt: must not + be + V3 → 'must not be shared'. Thông tin cá nhân không được chia sẻ với bên thứ ba khi chưa có sự đồng ý, một quy định pháp lý (như GDPR) mang tính bắt buộc cao nên 'must not' phù hợp hơn 'should not' (chỉ là khuyến nghị, không đủ mạnh về mặt pháp lý)." },
  { id: "p128", question: "The book _____ translated into over 50 languages so far.", options: ["is", "was", "has been", "had been"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành kèm 'so far': has been + V3 → 'has been translated' (book số ít). Cuốn sách đã được dịch sang hơn 50 thứ tiếng tính đến thời điểm hiện tại, và 'so far' là dấu hiệu đặc trưng của thì hiện tại hoàn thành (kết quả tích lũy đến bây giờ), khác với 'was' (quá khứ đơn, cần mốc thời gian xác định, không hợp với 'so far')." },
  { id: "p129", question: "A new exhibition _____ being set up in the gallery at the moment.", options: ["is", "was", "has been", "will be"], correctIndex: 0, explanation: "Bị động hiện tại tiếp diễn: is being + V3 → 'is being set up' (exhibition số ít). Một triển lãm mới đang được chuẩn bị trong phòng trưng bày ngay lúc này ('at the moment'), nên cần 'is being', khác với 'is' đơn thuần (sẽ mất đi nghĩa 'đang diễn ra')." },
  { id: "p130", question: "The ancient ruins _____ discovered by a local farmer in 1974.", options: ["are", "were", "have been", "had been"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn số nhiều: were + V3 → 'were discovered' (ruins). Tàn tích cổ được một nông dân địa phương phát hiện vào năm 1974, một mốc thời gian quá khứ cụ thể nên dùng 'were', không phải 'have been' (hiện tại hoàn thành, thường không đi cùng năm tháng cụ thể trong quá khứ như vậy)." },
  { id: "p131", question: "Seat belts _____ be worn at all times during the flight.", options: ["should", "must", "can", "might"], correctIndex: 1, explanation: "Modal bị động cho quy định an toàn: must + be + V3 → 'must be worn'. Dây an toàn phải được thắt trong suốt chuyến bay, một quy định bắt buộc trên máy bay nên 'must' phù hợp hơn 'should' (chỉ mang tính khuyên, không đủ nghiêm ngặt cho một yêu cầu an toàn hàng không)." },
  { id: "p132", question: "She was shocked when she heard she _____ promoted.", options: ["was being", "is", "had been", "will be"], correctIndex: 2, explanation: "Bị động thì quá khứ hoàn thành: had been + V3, dùng cho tin tức về việc đã xảy ra trước một thời điểm quá khứ khác → 'had been promoted'. Cô ấy đã được thăng chức trước khi nghe được tin đó (thời điểm 'was shocked'), nên cần mốc 'trước-quá khứ' này thay vì 'was being' (đang diễn ra, không hợp với một tin tức về việc đã hoàn tất)." },
  { id: "p133", question: "The missing child _____ found safe and well by a neighbor.", options: ["was", "is", "has been", "had been"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was found' (child số ít). Đứa trẻ mất tích được một người hàng xóm tìm thấy an toàn, một sự việc đã hoàn tất trong quá khứ nên dùng 'was', không phải 'has been' (hiện tại hoàn thành, ít phù hợp khi kể lại một sự việc cụ thể đã kết thúc theo cách tường thuật này)." },
  { id: "p134", question: "English _____ used as the official language at all international meetings.", options: ["is", "was", "has been", "will be"], correctIndex: 0, explanation: "Bị động hiện tại đơn cho thực tế đang áp dụng: is + V3 → 'is used' (English số ít). Tiếng Anh được dùng làm ngôn ngữ chính thức tại mọi cuộc họp quốc tế, một thực tế hiện hành nên dùng hiện tại đơn, không phải 'was' (quá khứ, ngụ ý điều này không còn đúng)." },
  { id: "p135", question: "The damage to the building _____ still being assessed.", options: ["is", "was", "has been", "will be"], correctIndex: 0, explanation: "Bị động hiện tại tiếp diễn: is being + V3 → 'is still being assessed' (damage số ít). Thiệt hại đối với tòa nhà vẫn đang được đánh giá, và 'still' cùng ngữ cảnh cho thấy hành động chưa hoàn tất, đang tiếp diễn nên cần 'is being', khác với 'is' đơn thuần (mất sắc thái 'đang')." },
  { id: "p136", question: "He _____ allowed to enter the building without a security badge.", options: ["is not", "was not", "has not been", "will not be"], correctIndex: 0, explanation: "Bị động hiện tại đơn phủ định: is not + V3 → 'is not allowed' (he số ít). Anh ta không được phép vào tòa nhà nếu không có thẻ an ninh, một quy định hiện hành nên dùng hiện tại đơn, không phải 'was not' (quá khứ, sai thì với một quy tắc đang áp dụng)." },
  { id: "p137", question: "The new employees _____ given a thorough training programme.", options: ["are", "were", "have been", "will be"], correctIndex: 3, explanation: "Bị động tương lai đơn: will be + V3 → 'will be given' (new employees). Nhân viên mới sẽ được đào tạo bài bản (trong tương lai), nên cần 'will be' chứ không phải 'are' hay 'have been' (không phù hợp với một kế hoạch/dự định sắp diễn ra)." },
  { id: "p138", question: "It _____ reported that several people were hurt in the blast.", options: ["is", "was", "has been", "had been"], correctIndex: 1, explanation: "Cấu trúc 'It + was/is + reported/said + that...' ở thể bị động dùng để tường thuật lại tin tức: was reported → 'It was reported that...'. Câu nói về một sự kiện đã được đưa tin trong quá khứ (vụ nổ đã xảy ra và có người bị thương), nên dùng 'was' chứ không phải 'is' (hiện tại, sai thì với một bản tin đã cũ)." },
  { id: "p139", question: "The famous painting _____ returned to its rightful owner.", options: ["was", "has been", "is being", "had been"], correctIndex: 1, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been returned' (painting số ít). Bức tranh nổi tiếng đã được trả lại cho chủ nhân hợp pháp, và kết quả này vẫn còn giá trị ở hiện tại nên dùng has been, không phải 'was' (quá khứ đơn, thiếu mốc thời gian xác định đi kèm)." },
  { id: "p140", question: "The prisoner _____ released after serving 10 years.", options: ["has been", "was", "is", "will be"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was released' (prisoner số ít). Tù nhân được thả sau khi thụ án 10 năm, một sự việc đã hoàn tất tại một thời điểm cụ thể trong quá khứ nên dùng 'was', không phải 'has been' (hiện tại hoàn thành, ít khi kèm theo mốc cụ thể như 'after serving 10 years' theo cách kể này)." },
  { id: "p141", question: "All forms _____ be completed in full before submission.", options: ["should", "must", "can", "are"], correctIndex: 1, explanation: "Modal bị động cho yêu cầu/hướng dẫn: must + be + V3 → 'must be completed'. Tất cả biểu mẫu phải được điền đầy đủ trước khi nộp, một yêu cầu bắt buộc nên 'must' phù hợp hơn 'should' (chỉ mang tính khuyên, không đủ nghiêm ngặt cho một thủ tục hành chính)." },
  { id: "p142", question: "The road _____ widened to accommodate more traffic.", options: ["is going to be", "is going", "will going to be", "is about be"], correctIndex: 0, explanation: "Kế hoạch tương lai ở thể bị động dùng đủ 'be going to' + be + V3 → 'is going to be widened' (road số ít). Con đường sẽ được mở rộng để đáp ứng lượng giao thông tăng, và công thức luôn cần 'be' đứng ngay trước V3, thiếu nó (như 'is going') sẽ sai ngữ pháp." },
  { id: "p143", question: "Thirty candidates _____ interviewed for the position.", options: ["will be", "are", "were", "have been"], correctIndex: 2, explanation: "Bị động thì quá khứ đơn số nhiều: were + V3 → 'were interviewed' (thirty candidates). Ba mươi ứng viên đã được phỏng vấn cho vị trí này, một sự việc đã hoàn tất trong quá khứ nên dùng 'were', không phải 'are' (hiện tại, sai thì) hay 'will be' (tương lai, chưa xảy ra)." },
  { id: "p144", question: "Electricity _____ generated from solar panels in this building.", options: ["is", "was", "has been", "will be"], correctIndex: 0, explanation: "Bị động hiện tại đơn cho thực tế đang vận hành: is + V3 → 'is generated' (electricity, không đếm được, số ít). Điện được tạo ra từ các tấm pin mặt trời trong tòa nhà này, một thực tế hiện hành nên dùng hiện tại đơn, không phải 'was' hay 'has been' (không hợp với một mô tả về hệ thống đang hoạt động)." },
  { id: "p145", question: "The issue _____ looked into by the relevant department.", options: ["is being", "is going to be", "will be", "has been"], correctIndex: 2, explanation: "Bị động tương lai đơn mang nghĩa cam kết: will be + V3 → 'will be looked into' (issue số ít). Vấn đề sẽ được bộ phận liên quan xem xét, một lời hứa giải quyết trong tương lai nên dùng 'will be', không phải 'is being' (đang diễn ra ngay bây giờ, chưa đúng với ý 'sẽ được xem xét')." },
  { id: "p146", question: "Surprisingly, no arrests _____ made despite the violent protest.", options: ["have been", "were", "had been", "are"], correctIndex: 0, explanation: "Bị động hiện tại hoàn thành: have been + V3 → 'have been made' (no arrests, số nhiều). Đáng ngạc nhiên là chưa có vụ bắt giữ nào được thực hiện dù có biểu tình bạo lực, và câu nhấn mạnh kết quả tính đến hiện tại nên dùng have been, không phải 'were' (quá khứ đơn, thiếu mốc thời gian cụ thể)." },
  { id: "p147", question: "His salary _____ increased three times in the last five years.", options: ["is", "was", "has been", "had been"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành kèm khung thời gian kéo dài: has been + V3 → 'has been increased' (salary số ít). Lương của anh ấy đã được tăng ba lần trong năm năm qua, và 'in the last five years' là khung thời gian tính đến hiện tại - đặc trưng của thì hiện tại hoàn thành, khác với 'was' (quá khứ đơn, cần một mốc thời gian xác định duy nhất, không phải một khoảng kéo dài đến nay)." },
  { id: "p148", question: "The temperature _____ controlled automatically by the thermostat.", options: ["is", "was", "will be", "has been"], correctIndex: 0, explanation: "Bị động hiện tại đơn cho cơ chế hoạt động hiện tại: is + V3 → 'is controlled' (temperature số ít). Nhiệt độ được điều khiển tự động bởi bộ điều nhiệt, một thực tế đang diễn ra thường xuyên nên dùng hiện tại đơn, không phải 'was' hay 'has been' (không phù hợp khi mô tả cách một hệ thống vận hành nói chung)." },
  { id: "p149", question: "The suspects _____ questioned separately to avoid collusion.", options: ["were", "are", "have been", "will be"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn số nhiều: were + V3 → 'were questioned' (suspects). Các nghi phạm bị thẩm vấn riêng lẻ để tránh thông đồng, một hành động đã xảy ra và hoàn tất nên dùng 'were', không phải 'are' (hiện tại, sai thì) hay 'will be' (tương lai, chưa xảy ra)." },
  { id: "p150", question: "A complaint _____ been filed against him by three former employees.", options: ["is", "was", "has", "had"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been filed' (a complaint số ít). Một đơn khiếu nại đã được ba cựu nhân viên nộp chống lại anh ta, và 'a complaint' là chủ ngữ số ít nên dùng 'has', không phải 'have' (sai hòa hợp chủ ngữ - động từ)." },
  { id: "p151", question: "The new airport terminal _____ inaugurated by the president next month.", options: ["is", "was", "will be", "has been"], correctIndex: 2, explanation: "Bị động tương lai đơn: will be + V3 → 'will be inaugurated' (terminal số ít). Nhà ga sân bay mới sẽ được tổng thống khánh thành vào tháng tới, một sự kiện đã lên kế hoạch cho tương lai nên dùng 'will be', không phải 'was' hay 'has been' (không hợp với mốc thời gian tương lai 'next month')." },
  { id: "p152", question: "Over 500 trees _____ planted in the area last spring.", options: ["are", "were", "have been", "had been"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn số nhiều: were + V3 → 'were planted' (over 500 trees). Hơn 500 cây đã được trồng trong khu vực này vào mùa xuân năm ngoái, và 'last spring' là mốc thời gian quá khứ rõ ràng nên dùng 'were', không phải 'have been' (hiện tại hoàn thành, ít khi đi cùng mốc thời gian đã xác định cụ thể như vậy)." },
  { id: "p153", question: "The exhibition _____ opened to the public next week.", options: ["is going to be", "is going to", "is", "will"], correctIndex: 0, explanation: "Kế hoạch tương lai đã sắp xếp trước ở thể bị động: 'be going to' + be + V3 → 'is going to be opened' (exhibition số ít). Triển lãm sẽ mở cửa cho công chúng vào tuần tới theo kế hoạch đã định, và công thức đầy đủ luôn cần 'be' trước V3, thiếu nó (như 'is going to' đơn thuần) sẽ không đúng ngữ pháp bị động." },
  { id: "p154", question: "Employees _____ not be discriminated against on the basis of gender.", options: ["must", "should", "can", "might"], correctIndex: 0, explanation: "Modal bị động cho luật lao động: must not + be + V3 → 'must not be discriminated against'. Nhân viên không được phép bị phân biệt đối xử vì giới tính, một quy định pháp lý bắt buộc nên dùng 'must not', không phải 'should' (chỉ mang tính khuyến nghị, không đủ mạnh về mặt pháp lý)." },
  { id: "p155", question: "The data _____ backed up daily to prevent data loss.", options: ["should be", "has been", "was", "will have been"], correctIndex: 0, explanation: "Modal bị động cho khuyến nghị/thực hành tốt: should + be + V3 → 'should be backed up'. Dữ liệu nên được sao lưu hằng ngày để tránh mất mát, đây là một lời khuyên thực hành tốt chứ không phải luật bắt buộc nên 'should' hợp lý hơn các thì đơn thuần như 'was' hay 'has been' (chỉ mô tả việc đã xảy ra, không phải khuyến nghị)." },
  { id: "p156", question: "The old factory _____ demolished last year to build a park.", options: ["has been", "was", "is", "had been"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was demolished' (factory số ít). Nhà máy cũ bị phá bỏ vào năm ngoái để xây công viên, và 'last year' là mốc thời gian quá khứ cụ thể nên dùng 'was', không phải 'has been' (hiện tại hoàn thành, ít khi kèm mốc thời gian đã xác định rõ như vậy)." },
  { id: "p157", question: "The information _____ kept strictly confidential at all times.", options: ["will be", "is", "must be", "has been"], correctIndex: 2, explanation: "Modal bị động cho yêu cầu bảo mật: must + be + V3 → 'must be kept'. Thông tin cần được giữ bí mật tuyệt đối mọi lúc, một yêu cầu nghiêm ngặt nên 'must be' phù hợp hơn các thì đơn thuần như 'is' hay 'will be' (thiếu sắc thái bắt buộc)." },
  { id: "p158", question: "The fire _____ brought under control within two hours.", options: ["is", "was", "has been", "will be"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was brought under control' (fire số ít). Đám cháy được khống chế trong vòng hai giờ, một sự việc đã xảy ra và kết thúc nên dùng 'was', không phải 'has been' (hiện tại hoàn thành, ít phù hợp với việc kể lại một sự kiện đã hoàn tất cụ thể theo mốc thời gian 'within two hours' này)." },
  { id: "p159", question: "A new approach to teaching _____ trialled in several schools.", options: ["is being", "was being", "has been", "will be"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been trialled' (approach số ít). Một phương pháp giảng dạy mới đã được thử nghiệm tại nhiều trường học, và kết quả này còn liên quan đến hiện tại nên dùng has been, không phải 'is being' (chỉ diễn tả việc đang diễn ra ngay lúc nói, không nhấn mạnh kết quả tích lũy)." },
  { id: "p160", question: "The stolen artwork _____ recovered by police in a dramatic raid.", options: ["was", "is", "has been", "had been"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was recovered' (artwork số ít). Tác phẩm nghệ thuật bị đánh cắp được cảnh sát thu hồi trong một cuộc đột kích, một sự việc cụ thể đã xảy ra và kết thúc nên dùng 'was', không phải 'has been' (hiện tại hoàn thành, ít phù hợp với cách kể một sự kiện cụ thể mang tính tường thuật này)." },
  { id: "p161", question: "Safety helmets _____ worn at all times on the construction site.", options: ["must be", "should be", "can be", "might be"], correctIndex: 0, explanation: "Modal bị động cho quy định an toàn lao động: must + be + V3 → 'must be worn'. Mũ bảo hộ phải được đội mọi lúc tại công trường xây dựng, một quy định bắt buộc về an toàn nên 'must' phù hợp hơn 'should' (chỉ mang tính khuyến cáo)." },
  { id: "p162", question: "His remarkable recovery _____ attributed to the new treatment.", options: ["was", "is", "has been", "will be"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been attributed' (recovery số ít). Sự hồi phục đáng kinh ngạc của anh ấy được quy cho phương pháp điều trị mới, một kết luận vẫn còn giá trị ở hiện tại nên dùng has been, không phải 'was' (quá khứ đơn, ít phù hợp khi diễn tả một nhận định/kết luận đang được chấp nhận)." },
  { id: "p163", question: "The concert _____ cancelled due to bad weather.", options: ["is", "was", "has been", "will be"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been cancelled' (concert số ít). Buổi hòa nhạc bị hủy do thời tiết xấu, và thông báo này vẫn còn ảnh hưởng ở hiện tại (buổi diễn sẽ không diễn ra) nên dùng has been, không phải 'was' (quá khứ đơn, chỉ đơn thuần kể lại sự việc mà không nhấn mạnh tình trạng hiện tại)." },
  { id: "p164", question: "The meeting was called off because a decision _____ already reached.", options: ["is", "was", "has been", "had been"], correctIndex: 3, explanation: "Bị động thì quá khứ hoàn thành: had been + V3, dùng cho hành động xảy ra trước một sự việc quá khứ khác → 'had been reached'. Quyết định đã được đưa ra trước khi cuộc họp bị hủy bỏ, nên cần mốc 'trước-quá khứ' này thay vì 'was' (chỉ quá khứ đơn thuần, không làm rõ trình tự trước-sau)." },
  { id: "p165", question: "The victim _____ taken to hospital in a critical condition.", options: ["was", "is", "has been", "will be"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was taken' (victim số ít). Nạn nhân được đưa đến bệnh viện trong tình trạng nguy kịch, một hành động đã xảy ra và hoàn tất nên dùng 'was', không phải 'is' (hiện tại, sai thì) hay 'has been' (hoàn thành, ít hợp với cách kể một sự việc cụ thể như vậy)." },
  { id: "p166", question: "Fees _____ reviewed annually and may increase each year.", options: ["are", "were", "will be", "have been"], correctIndex: 0, explanation: "Bị động hiện tại đơn cho quy trình thường xuyên: are + V3 → 'are reviewed' (fees số nhiều). Phí được xem xét lại hàng năm và có thể tăng mỗi năm, một quy trình lặp lại đều đặn nên dùng hiện tại đơn, không phải 'were' (quá khứ, sai thì) hay 'will be' (tương lai, không hợp với một quy trình đang áp dụng thường xuyên)." },
  { id: "p167", question: "The message _____ delivered before he left the office.", options: ["was", "had been", "has been", "is"], correctIndex: 1, explanation: "Bị động thì quá khứ hoàn thành: had been + V3, diễn tả hành động hoàn tất trước một mốc quá khứ khác → 'had been delivered'. Tin nhắn đã được chuyển đi trước khi anh ta rời văn phòng, nên cần mốc 'trước-quá khứ' này thay vì 'was' (chỉ quá khứ đơn thuần, thiếu ý nghĩa 'đã xong trước khi...')." },
  { id: "p168", question: "The suspect _____ placed under surveillance for months before the arrest.", options: ["has been", "was", "had been", "is"], correctIndex: 2, explanation: "Bị động thì quá khứ hoàn thành: had been + V3, dùng cho hành động kéo dài trước một mốc quá khứ khác → 'had been placed'. Nghi phạm đã bị theo dõi trong nhiều tháng trước khi bị bắt, nên cần mốc 'trước-quá khứ' này (before the arrest) thay vì 'was' (chỉ đơn thuần quá khứ, không thể hiện rõ trình tự trước sự kiện bị bắt)." },
  { id: "p169", question: "All applications _____ processed within three working days.", options: ["will be", "are", "were", "have been"], correctIndex: 0, explanation: "Bị động tương lai đơn: will be + V3 → 'will be processed' (applications số nhiều). Tất cả đơn đăng ký sẽ được xử lý trong vòng ba ngày làm việc, một cam kết về thời gian xử lý trong tương lai nên dùng 'will be', không phải 'are' hay 'have been' (không phù hợp với một lời hứa về tương lai)." },
  { id: "p170", question: "The historic castle _____ damaged in last night's storm.", options: ["is", "was", "has been", "will be"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been damaged' (castle số ít). Lâu đài cổ bị hư hại trong trận bão đêm qua, và hậu quả này vẫn còn ảnh hưởng đến hiện tại nên dùng has been, không phải 'was' (quá khứ đơn, ít nhấn mạnh kết quả hiện tại bằng has been trong ngữ cảnh này)." },
  { id: "p171", question: "He claims he _____ given the wrong information.", options: ["is", "was", "has been", "had been"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been given' (he số ít). Anh ta tuyên bố mình đã bị cung cấp thông tin sai, và việc này vẫn còn ảnh hưởng/liên quan đến hiện tại (anh ta đang khiếu nại) nên dùng has been, không phải 'was' (quá khứ đơn, ít phù hợp với ngữ cảnh một lời tuyên bố đang diễn ra ở hiện tại)." },
  { id: "p172", question: "The medication _____ taken with food to avoid stomach upset.", options: ["should be", "must be", "can be", "might be"], correctIndex: 0, explanation: "Modal bị động cho lời khuyên y tế: should + be + V3 → 'should be taken'. Thuốc nên được uống cùng thức ăn để tránh khó chịu dạ dày, đây là một khuyến nghị/hướng dẫn sử dụng nên 'should' phù hợp hơn 'must' (mang tính bắt buộc nghiêm ngặt hơn mức cần thiết cho một lời khuyên thông thường)." },
  { id: "p173", question: "The prisoner _____ not been heard from since he escaped.", options: ["has", "had", "is", "was"], correctIndex: 0, explanation: "Bị động hiện tại hoàn thành phủ định: has not been + V3 → 'has not been heard from' (prisoner số ít). Chưa có tin tức gì về tù nhân kể từ khi anh ta trốn thoát, và 'since' (kể từ khi) là dấu hiệu điển hình đi cùng thì hiện tại hoàn thành, khác với 'had' (quá khứ hoàn thành, không hợp vì hành động vẫn kéo dài đến hiện tại)." },
  { id: "p174", question: "A monument _____ erected in memory of those who died.", options: ["was", "has been", "is being", "will be"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was erected' (monument số ít). Một đài tưởng niệm được dựng lên để tưởng nhớ những người đã khuất, một sự việc đã hoàn tất trong quá khứ nên dùng 'was', không phải 'has been' (hiện tại hoàn thành, ít phù hợp bằng 'was' khi mô tả một công trình cụ thể đã được dựng xong)." },
  { id: "p175", question: "The report _____ being discussed when I arrived.", options: ["is", "was", "has been", "had been"], correctIndex: 1, explanation: "Bị động thì quá khứ tiếp diễn: was being + V3 → 'was being discussed' (report số ít). Báo cáo đang được thảo luận đúng lúc người nói đến nơi, nên cần diễn tả hành động đang xảy ra tại thời điểm đó, khác với 'is' (hiện tại, sai thì) hay 'had been' (hoàn thành, ngụ ý đã xong trước khi đến, không phải đang diễn ra)." },
  { id: "p176", question: "His contributions _____ recognized with a special award.", options: ["are", "were", "have been", "will be"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: have been + V3 → 'have been recognized' (contributions số nhiều). Những đóng góp của anh ấy đã được ghi nhận bằng một giải thưởng đặc biệt, và kết quả này còn giá trị đến hiện tại nên dùng have been, không phải 'were' (quá khứ đơn, ít nhấn mạnh sự công nhận này vẫn còn ý nghĩa ở hiện tại)." },
  { id: "p177", question: "The bridge _____ closed for repairs for the next six months.", options: ["is", "will be", "has been", "was"], correctIndex: 1, explanation: "Bị động tương lai đơn: will be + V3 → 'will be closed' (bridge số ít). Cây cầu sẽ bị đóng để sửa chữa trong sáu tháng tới, một thông báo về tương lai nên dùng 'will be', không phải 'is' (hiện tại, sai thì) hay 'has been' (hoàn thành, không hợp với khoảng thời gian tương lai 'for the next six months')." },
  { id: "p178", question: "Voters _____ urged to check their registration details online.", options: ["are", "were", "have been", "will be"], correctIndex: 0, explanation: "Bị động hiện tại đơn: are + V3 → 'are urged' (voters số nhiều). Cử tri được kêu gọi kiểm tra lại thông tin đăng ký trực tuyến, một lời khuyên/thông báo mang tính hiện hành nên dùng hiện tại đơn, không phải 'were' (quá khứ, sai thì với một lời kêu gọi đang có hiệu lực)." },
  { id: "p179", question: "The patient _____ discharged from hospital yesterday.", options: ["is", "was", "has been", "will be"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was discharged' (patient số ít). Bệnh nhân được xuất viện vào ngày hôm qua, và 'yesterday' là mốc thời gian quá khứ rõ ràng nên dùng 'was', không phải 'is' (hiện tại, sai thì) hay 'has been' (hoàn thành, ít khi đi cùng 'yesterday' - mốc thời gian đã xác định cụ thể)." },
  { id: "p180", question: "These machines _____ not be operated without proper training.", options: ["must", "should", "can", "are"], correctIndex: 0, explanation: "Modal bị động cho quy định an toàn: must not + be + V3 → 'must not be operated'. Những máy móc này không được vận hành nếu chưa qua đào tạo phù hợp, một quy định bắt buộc về an toàn lao động nên dùng 'must' thay vì 'should' (chỉ mang tính khuyến cáo, không đủ nghiêm khắc)." },
  { id: "p181", question: "The new rules _____ expected to come into effect next January.", options: ["are", "were", "will be", "have been"], correctIndex: 0, explanation: "Với động từ tường thuật bị động 'are expected' + hành động sắp xảy ra, theo sau bằng 'to' + động từ nguyên mẫu chủ động (vì 'come into effect' là nội động từ) → 'are expected to come into effect'. Các quy định mới được kỳ vọng sẽ có hiệu lực vào tháng Giêng tới, và 'are' phù hợp vì bản thân việc 'kỳ vọng' đang diễn ra ở hiện tại, khác với 'were' (quá khứ, sai thì)." },
  { id: "p182", question: "The proposal _____ voted on at the general assembly.", options: ["will be", "is being", "has been", "was"], correctIndex: 0, explanation: "Bị động tương lai đơn: will be + V3 → 'will be voted on' (proposal số ít). Đề xuất sẽ được biểu quyết tại đại hội đồng, một sự kiện dự kiến trong tương lai nên dùng 'will be', không phải 'is being' (đang diễn ra ngay bây giờ) hay 'was' (quá khứ, chưa xảy ra)." },
  { id: "p183", question: "The suspect's alibi _____ checked out by the detectives.", options: ["was", "has been", "is", "will be"], correctIndex: 1, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been checked out' (alibi số ít). Bằng chứng ngoại phạm của nghi phạm đã được các thám tử xác minh, và kết quả này vẫn còn giá trị/liên quan đến hiện tại nên dùng has been, không phải 'was' (quá khứ đơn, ít nhấn mạnh việc xác minh này vừa hoàn tất và có ý nghĩa ở hiện tại)." },
  { id: "p184", question: "She _____ offered the job before the interview was even over.", options: ["was", "is", "has been", "had been"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was offered' (she số ít). Cô ấy được đề nghị nhận công việc trước khi buổi phỏng vấn kết thúc, một sự việc cụ thể xảy ra trong quá khứ nên dùng 'was', không phải 'has been' (hiện tại hoàn thành, ít phù hợp khi kể lại trình tự một sự việc cụ thể đã qua như vậy)." },
  { id: "p185", question: "The stadium _____ renovated between 2020 and 2022.", options: ["is", "was", "has been", "had been"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was renovated' (stadium số ít). Sân vận động được cải tạo trong khoảng thời gian từ 2020 đến 2022, một khoảng thời gian đã kết thúc trong quá khứ nên dùng 'was', không phải 'has been' (hiện tại hoàn thành, thường không đi cùng một khoảng thời gian đã khép lại rõ ràng như '2020 and 2022')." },
  { id: "p186", question: "Masks _____ be worn in all indoor public spaces during the pandemic.", options: ["must", "should", "could", "might"], correctIndex: 0, explanation: "Modal bị động cho quy định bắt buộc trong đại dịch: must + be + V3 → 'must be worn'. Khẩu trang phải được đeo tại mọi không gian công cộng trong nhà trong thời kỳ đại dịch, một quy định y tế bắt buộc nên 'must' phù hợp hơn 'should' hay 'could' (đều không đủ mạnh cho một yêu cầu bắt buộc)." },
  { id: "p187", question: "The crime _____ have been prevented if more security cameras had been installed.", options: ["could", "would", "should", "might"], correctIndex: 0, explanation: "Modal bị động ở câu điều kiện loại 3: could + have been + V3 → 'could have been prevented'. Tội ác có lẽ đã có thể được ngăn chặn nếu có nhiều camera an ninh hơn được lắp đặt, một giả định về khả năng đã bị bỏ lỡ trong quá khứ nên cần 'could have been' đầy đủ, không chỉ 'would' hay 'should' (khác sắc thái ý nghĩa với 'khả năng có thể đã')." },
  { id: "p188", question: "Thousands of pounds _____ raised for charity during the marathon.", options: ["are", "were", "have been", "will be"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: have been + V3 → 'have been raised' (thousands of pounds). Hàng ngàn bảng Anh đã được quyên góp cho từ thiện trong cuộc chạy marathon, và kết quả tích lũy này vẫn còn ý nghĩa ở hiện tại nên dùng have been, không phải 'were' (quá khứ đơn, ít nhấn mạnh tính tích lũy kết quả này)." },
  { id: "p189", question: "The error _____ not have been made if the instructions had been followed.", options: ["would", "could", "might", "should"], correctIndex: 0, explanation: "Modal bị động ở câu điều kiện loại 3 phủ định: would not + have been + V3 → 'would not have been made'. Lỗi lẽ ra đã không xảy ra nếu hướng dẫn được tuân thủ, một giả định trái với những gì đã thực sự xảy ra trong quá khứ nên cần 'would not have been' đầy đủ, khác với 'could' hay 'might' (mang sắc thái khả năng chứ không phải kết quả tất yếu như 'would')." },
  { id: "p190", question: "New technology _____ constantly being developed to combat cybercrime.", options: ["is", "was", "has been", "will be"], correctIndex: 0, explanation: "Bị động hiện tại tiếp diễn: is being + V3 → 'is constantly being developed' (technology, không đếm được, số ít). Công nghệ mới liên tục được phát triển để chống lại tội phạm mạng, và 'constantly' cùng ngữ cảnh cho thấy một quá trình đang không ngừng diễn ra nên cần 'is being', khác với 'is' đơn thuần (mất sắc thái 'đang diễn ra liên tục')." },
  { id: "p191", question: "The missing funds _____ traced back to an unauthorized transaction.", options: ["have been", "are", "were", "had been"], correctIndex: 0, explanation: "Bị động hiện tại hoàn thành: have been + V3 → 'have been traced' (the missing funds, số nhiều). Khoản tiền bị thất thoát đã được lần ra dấu vết dẫn đến một giao dịch trái phép, và kết quả điều tra này vẫn còn liên quan ở hiện tại nên dùng have been, không phải 'were' (quá khứ đơn, ít nhấn mạnh kết quả điều tra tính đến hiện tại)." },
  { id: "p192", question: "The bill _____ passed by a narrow majority in parliament.", options: ["was", "is", "has been", "will be"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was passed' (bill số ít). Dự luật được thông qua với đa số sít sao tại quốc hội, một sự việc đã hoàn tất trong quá khứ nên dùng 'was', không phải 'is' (hiện tại, sai thì) hay 'has been' (hoàn thành, ít phù hợp khi kể lại một sự kiện lập pháp cụ thể như vậy)." },
  { id: "p193", question: "Visitors _____ reminded not to touch the exhibits.", options: ["are", "were", "will be", "have been"], correctIndex: 0, explanation: "Bị động hiện tại đơn: are + V3 → 'are reminded' (visitors số nhiều). Du khách được nhắc nhở không chạm vào hiện vật trưng bày, một thông báo mang tính thường trực/áp dụng liên tục nên dùng hiện tại đơn, không phải 'were' (quá khứ, sai thì với một quy tắc đang áp dụng)." },
  { id: "p194", question: "The historic building _____ listed as a heritage site in 1985.", options: ["is", "was", "has been", "had been"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was listed' (building số ít). Tòa nhà lịch sử được xếp hạng là di sản vào năm 1985, một mốc thời gian quá khứ cụ thể nên dùng 'was', không phải 'has been' (hiện tại hoàn thành, ít khi đi cùng một năm cụ thể trong quá khứ như '1985' theo cách này)." },
  { id: "p195", question: "All complaints _____ investigated thoroughly by the internal review team.", options: ["will be", "are", "were", "have been"], correctIndex: 0, explanation: "Bị động tương lai đơn: will be + V3 → 'will be investigated' (complaints số nhiều). Mọi khiếu nại sẽ được đội ngũ rà soát nội bộ điều tra kỹ lưỡng, một cam kết về quy trình xử lý trong tương lai nên dùng 'will be', không phải 'are' hay 'have been' (không phù hợp với một cam kết hướng tới tương lai)." },
  { id: "p196", question: "The manuscript _____ believed to date back to the 12th century.", options: ["is", "was", "has been", "will be"], correctIndex: 0, explanation: "Với động từ tường thuật bị động 'is believed' diễn tả một nhận định đang được tin là đúng ở hiện tại, dùng 'is' + V3 → 'is believed'. Bản thảo được cho là có niên đại từ thế kỷ 12, và chính động từ 'believe' ở đây chia hiện tại đơn vì đó là nhận định hiện nay của giới học giả, khác với 'was' (quá khứ, ngụ ý nhận định đó không còn được tin nữa)." },
  { id: "p197", question: "The new school year _____ officially kicked off last September.", options: ["is", "was", "has been", "will be"], correctIndex: 1, explanation: "Bị động thì quá khứ đơn: was + V3 → 'was kicked off' (school year số ít). Năm học mới chính thức khai giảng vào tháng Chín năm ngoái, và 'last September' là mốc thời gian quá khứ rõ ràng nên dùng 'was', không phải 'is' (hiện tại, sai thì) hay 'has been' (hoàn thành, ít phù hợp với mốc thời gian đã xác định cụ thể như vậy)." },
  { id: "p198", question: "The culprit _____ caught on CCTV entering the building.", options: ["was", "is", "has been", "had been"], correctIndex: 0, explanation: "Bị động thì quá khứ đơn kết hợp cụm từ chỉ phương tiện ghi hình: was + V3 → 'was caught' (culprit số ít). Thủ phạm bị camera an ninh ghi lại cảnh đang đột nhập vào tòa nhà, một sự việc cụ thể đã xảy ra và được ghi nhận nên dùng 'was', không phải 'is' (hiện tại, sai thì) hay 'has been' (hoàn thành, ít phù hợp khi mô tả một khoảnh khắc cụ thể bị quay lại như vậy)." },
  { id: "p199", question: "More than 2 million doses of the vaccine _____ administered in the first week.", options: ["are", "were", "have been", "will be"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: have been + V3 → 'have been administered' (more than 2 million doses, số nhiều). Hơn 2 triệu liều vắc-xin đã được tiêm trong tuần đầu tiên, và đây là kết quả tích lũy tính đến hiện tại nên dùng have been, không phải 'were' (quá khứ đơn, ít nhấn mạnh tính tích lũy của con số này)." },
  { id: "p200", question: "The old market _____ replaced by a modern shopping complex.", options: ["was", "is", "has been", "will be"], correctIndex: 2, explanation: "Bị động hiện tại hoàn thành: has been + V3 → 'has been replaced' (market số ít). Khu chợ cũ đã được thay thế bằng một trung tâm mua sắm hiện đại, và đây là thực trạng hiện nay (kết quả của sự thay đổi) nên dùng has been, không phải 'was' (quá khứ đơn, ít nhấn mạnh bằng has been khi mô tả tình trạng hiện tại của khu vực này)." },
];
